package com.chesspulseai.service;
import com.chesspulseai.dto.*; import com.chesspulseai.engine.*; import com.chesspulseai.entity.*; import com.chesspulseai.enumtype.*; import com.chesspulseai.exception.*; import com.chesspulseai.mapper.GameMapper; import com.chesspulseai.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class GameService { private final GameRepository games; private final ChessMoveRepository moves; private final PositionAnalysisRepository analyses; private final GameMapper mapper; private final ChessPositionService chess; private final StockfishClient engine; private final ProbabilityService probabilities; private final GamePhaseDetector phase; private final CoachingService coaching; public GameService(GameRepository g,ChessMoveRepository m,PositionAnalysisRepository a,GameMapper mp,ChessPositionService c,StockfishClient e,ProbabilityService p,GamePhaseDetector ph,CoachingService co){games=g;moves=m;analyses=a;mapper=mp;chess=c;engine=e;probabilities=p;phase=ph;coaching=co;} public GameResponse create(CreateGameRequest r){Game g=new Game();g.setWhitePlayer(r.whitePlayer().trim());g.setBlackPlayer(r.blackPlayer().trim());g.setPlayerColor(r.playerColor());return mapper.game(games.save(g));} @Transactional(readOnly=true) public List<GameResponse> list(){return games.findAllByStatusOrderByCreatedAtDesc(GameStatus.COMPLETED).stream().map(mapper::game).toList();} @Transactional(readOnly=true) public GameResponse get(UUID id){return mapper.game(game(id));} public void delete(UUID id){games.delete(game(id));}
 public MoveResponse add(UUID id,AddMoveRequest req){Game g=game(id);if(g.getStatus()!=GameStatus.IN_PROGRESS)throw new IllegalChessMoveException("The game has already ended");List<ChessMove> old=moves.findDetailedByGameId(g.getId());ChessPositionService.AppliedMove applied=chess.apply(old.stream().map(ChessMove::getUci).toList(),req.uciMove());PlayerColor color=old.size()%2==0?PlayerColor.WHITE:PlayerColor.BLACK;ChessMove m=new ChessMove();m.setGame(g);m.setMoveNumber(old.size()+1);m.setSan(applied.san());m.setUci(req.uciMove().toLowerCase());m.setFen(applied.fen());m.setPlayerColor(color);m=moves.save(m);EngineEvaluation raw=applied.completed()?new EngineEvaluation(null,null,null,"",0):engine.evaluate(applied.fen());Integer whiteCp=normalizeToWhite(raw.centipawns(),applied.fen());Integer whiteMate=normalizeMateToWhite(raw.mateScore(),applied.fen());ProbabilityResponse pr=applied.completed()?probabilities.terminal(applied.result()):probabilities.from(whiteCp,whiteMate);PositionAnalysis a=new PositionAnalysis();a.setMove(m);a.setEvaluation(whiteCp);a.setMateScore(whiteMate);a.setBestMove(raw.bestMove());a.setPrincipalVariation(raw.principalVariation());a.setDepth(raw.depth());a.setWhiteProbability(pr.white());a.setBlackProbability(pr.black());a.setDrawProbability(pr.draw());a.setGamePhase(phase.detect(applied.fen()));a.setCoachingExplanation(applied.completed()?terminalMessage(applied.result()):coaching.explain(color,new EngineEvaluation(whiteCp,whiteMate,raw.bestMove(),raw.principalVariation(),raw.depth())));m.setAnalysis(analyses.save(a));if(applied.completed()){g.setStatus(GameStatus.COMPLETED);g.setResult(applied.result());g.setEndTime(Instant.now());}return mapper.move(m);} private Integer normalizeToWhite(Integer cp,String fen){if(cp==null)return null;return fen.split(" ")[1].equals("b")?-cp:cp;} private Integer normalizeMateToWhite(Integer mate,String fen){if(mate==null)return null;return fen.split(" ")[1].equals("b")?-mate:mate;} private String terminalMessage(GameResult result){return switch(result){case WHITE_WIN->"Checkmate. White wins the game.";case BLACK_WIN->"Checkmate. Black wins the game.";case DRAW->"The game is legally drawn.";default->"";};}
 @Transactional(readOnly=true) public List<MoveResponse> moveList(UUID id){Game g=game(id);return moves.findDetailedByGameId(g.getId()).stream().map(mapper::move).toList();} @Transactional(readOnly=true) public List<TurningPointResponse> turningPoints(UUID id){List<ChessMove> all=moves.findDetailedByGameId(game(id).getId());List<TurningPointResponse> out=new ArrayList<>();for(int i=1;i<all.size();i++){PositionAnalysis before=all.get(i-1).getAnalysis(),after=all.get(i).getAnalysis();if(before==null||after==null)continue;ChessMove m=all.get(i);double swing=Math.abs(after.getWhiteProbability()-before.getWhiteProbability());out.add(new TurningPointResponse(m.getMoveNumber(),m.getSan(),m.getPlayerColor(),after.getGamePhase(),prob(before),prob(after),Math.round(swing*10d)/10d,after.getBestMove(),after.getPrincipalVariation(),after.getDepth(),after.getMateScore(),after.getCoachingExplanation()));}return out.stream().sorted(Comparator.comparingDouble(TurningPointResponse::probabilitySwing).reversed()).limit(5).toList();} private ProbabilityResponse prob(PositionAnalysis a){return new ProbabilityResponse(a.getWhiteProbability(),a.getBlackProbability(),a.getDrawProbability());} private Game game(UUID id){return games.findByPublicId(id.toString()).orElseThrow(()->new ResourceNotFoundException("Game not found"));}}
